S.append(story("opas_geschichte", "A2-1", "Opas Geschichte",
 ("Ông kể cho Lea nghe ông và bà đã quen nhau thế nào. Trong một chiếc thùng cũ có một lá thư.", "Grandpa tells Lea how he and Grandma met. In an old box there is a letter."),
 ["Fabrik", "Kiste", "Gedicht"],
 [("N", "Am Sonntag besucht Lea ihren Opa.", "Chủ nhật Lea đến thăm ông.", "On Sunday Lea visits her grandpa."),
  ("N", "Opa ist schon sehr alt, aber er erzählt gern Geschichten.", "Ông đã rất già, nhưng ông thích kể chuyện.", "Grandpa is very old, but he likes telling stories."),
  ("N", "Heute zeigt er Lea ein altes Foto.", "Hôm nay ông cho Lea xem một bức ảnh cũ.", "Today he shows Lea an old photo."),
  ("A", "Das bin ich. Damals war ich zwanzig Jahre alt.", "Đây là ông. Hồi đó ông hai mươi tuổi.", "That's me. Back then I was twenty."),
  ("B", "Und wer ist die junge Frau neben dir?", "Thế cô gái trẻ bên cạnh ông là ai ạ?", "And who is the young woman next to you?"),
  ("A", "Das ist deine Oma.", "Đó là bà của cháu.", "That is your grandma."),
  ("N", "Opa erzählt von der Vergangenheit.", "Ông kể về quá khứ.", "Grandpa talks about the past."),
  ("A", "Damals war das Leben schwer. Es gab wenig Geld.", "Hồi đó cuộc sống khó khăn. Có rất ít tiền.", "Back then life was hard. There was little money."),
  ("A", "Ich habe in einer Fabrik gearbeitet, jeden Tag zehn Stunden.", "Ông làm việc trong một nhà máy, mỗi ngày mười tiếng.", "I worked in a factory, ten hours every day."),
  ("N", "Lea hört genau zu.", "Lea chăm chú lắng nghe.", "Lea listens carefully."),
  ("B", "Und wie hast du Oma gefunden?", "Thế ông gặp bà như thế nào ạ?", "And how did you find Grandma?"),
  ("A", "Sie hat in einem Geschäft neben der Fabrik gearbeitet.", "Bà làm việc trong một cửa hàng cạnh nhà máy.", "She worked in a shop next to the factory."),
  ("A", "Ich habe jeden Tag eine Blume für sie gekauft.", "Ngày nào ông cũng mua một bông hoa cho bà.", "Every day I bought a flower for her."),
  ("A", "Nach einem Monat habe ich sie gefragt: Willst du mich heiraten?", "Sau một tháng ông hỏi bà: Em có muốn lấy anh không?", "After a month I asked her: Will you marry me?"),
  ("B", "Und was hat sie gesagt?", "Thế bà nói gì ạ?", "And what did she say?"),
  ("A", "Sie hat gelacht und gesagt: Du bist verrückt!", "Bà cười và nói: Anh điên à!", "She laughed and said: You're crazy!"),
  ("A", "Aber eine Woche später hat sie ja gesagt.", "Nhưng một tuần sau bà đã đồng ý.", "But a week later she said yes."),
  ("N", "Lea lacht auch.", "Lea cũng bật cười.", "Lea laughs too."),
  ("N", "Dann holt Opa einen alten Brief aus einer Kiste.", "Rồi ông lấy một lá thư cũ từ trong một chiếc thùng.", "Then Grandpa takes an old letter out of a box."),
  ("A", "Den Brief hat Oma mir damals geschrieben. Lies ihn.", "Lá thư này hồi đó bà viết cho ông. Cháu đọc đi.", "Grandma wrote me this letter back then. Read it."),
  ("N", "Im Brief steht ein kleines Gedicht: Ich liebe dich, für immer.", "Trong thư có một bài thơ nhỏ: Em yêu anh, mãi mãi.", "In the letter there is a little poem: I love you, for ever."),
  ("N", "Opa ist ein bisschen traurig, aber auch glücklich.", "Ông hơi buồn, nhưng cũng hạnh phúc.", "Grandpa is a little sad, but also happy."),
  ("B", "Opa, ich bin froh, dass du mir das erzählt hast.", "Ông ơi, cháu rất vui vì ông đã kể cho cháu nghe.", "Grandpa, I'm glad you told me that."),
  ("A", "Die Vergangenheit ist wichtig. Aber die Zukunft gehört dir!", "Quá khứ quan trọng. Nhưng tương lai là của cháu!", "The past is important. But the future belongs to you!")],
 [("locate", "Hồi trẻ bà làm việc ở đâu?", "Where did Grandma work when she was young?", [("Trong một nhà máy", "In a factory"), ("Trong một cửa hàng cạnh nhà máy", "In a shop next to the factory"), ("Ở bệnh viện", "In a hospital")], 1),
  ("locate", "Ngày nào ông cũng mua gì cho bà?", "What did Grandpa buy for Grandma every day?", [("Một bông hoa", "A flower"), ("Một cái bánh", "A cake"), ("Một quyển sách", "A book")], 0),
  ("infer", "Bao lâu sau khi ông cầu hôn thì bà đồng ý?", "How long after Grandpa's proposal did Grandma say yes?", [("Ngay hôm đó", "The same day"), ("Một tháng sau", "A month later"), ("Một tuần sau", "A week later")], 2)],
 names=["Lea"]))

S.append(story("kochen_mit_oma", "A2-1", "Kochen mit Oma",
 ("Tim nấu súp cùng bà. Cậu cho quá nhiều muối — nhưng bà có một mẹo hay.", "Tim cooks soup with his grandma. He adds far too much salt — but Grandma has a good trick."),
 ["mischen", "Magen", "Keks"],
 [("N", "Tim ist zehn Jahre alt. Am Samstag ist er bei seiner Oma.", "Tim mười tuổi. Thứ Bảy cậu ở nhà bà.", "Tim is ten. On Saturday he is at his grandma's."),
  ("B", "Heute kochen wir zusammen. Hast du Hunger?", "Hôm nay bà cháu mình cùng nấu ăn. Cháu có đói không?", "Today we're cooking together. Are you hungry?"),
  ("A", "Ja, sehr! Was kochen wir?", "Có ạ, đói lắm! Mình nấu món gì ạ?", "Yes, very! What are we cooking?"),
  ("B", "Eine Suppe mit Fleisch und Gemüse.", "Một nồi súp có thịt và rau.", "A soup with meat and vegetables."),
  ("N", "Zuerst holt Tim alles aus dem Kühlschrank: Fleisch, Kartoffeln und Tomaten.", "Trước tiên Tim lấy mọi thứ ra khỏi tủ lạnh: thịt, khoai tây và cà chua.", "First Tim takes everything out of the fridge: meat, potatoes and tomatoes."),
  ("B", "Jetzt schneiden wir das Gemüse. Aber Vorsicht mit den Händen!", "Giờ mình thái rau. Nhưng cẩn thận tay đấy!", "Now we cut the vegetables. But careful with your hands!"),
  ("N", "Tim schneidet die Kartoffeln ganz langsam.", "Tim thái khoai tây thật chậm.", "Tim cuts the potatoes very slowly."),
  ("N", "Oma macht den Herd an und gibt Öl, Fleisch und Wasser dazu.", "Bà bật bếp rồi cho dầu, thịt và nước vào.", "Grandma switches on the stove and adds oil, meat and water."),
  ("N", "Dann mischt Tim das Gemüse in die Suppe.", "Rồi Tim cho rau vào súp và khuấy đều.", "Then Tim mixes the vegetables into the soup."),
  ("B", "Jetzt brauchen wir Salz. Aber nicht zu viel!", "Giờ mình cần muối. Nhưng đừng nhiều quá nhé!", "Now we need salt. But not too much!"),
  ("N", "Tim gibt Salz in die Suppe. Sehr viel Salz.", "Tim cho muối vào súp. Rất nhiều muối.", "Tim puts salt in the soup. A lot of salt."),
  ("B", "Tim! Das war zu viel!", "Tim! Nhiều quá rồi!", "Tim! That was too much!"),
  ("A", "Oh nein! Entschuldigung, Oma.", "Ôi không! Cháu xin lỗi bà.", "Oh no! Sorry, Grandma."),
  ("B", "Kein Problem. Ich habe eine Idee.", "Không sao. Bà có một ý.", "No problem. I have an idea."),
  ("N", "Oma gibt mehr Wasser und noch eine Kartoffel in die Suppe.", "Bà cho thêm nước và thêm một củ khoai tây vào súp.", "Grandma puts more water and another potato into the soup."),
  ("B", "Die Kartoffel nimmt das Salz. Das hat mir meine Mutter erklärt.", "Củ khoai tây sẽ hút bớt muối. Mẹ của bà đã chỉ cho bà điều đó.", "The potato takes up the salt. My mother explained that to me."),
  ("N", "Nach einer Stunde riecht die ganze Wohnung gut.", "Sau một tiếng, cả căn hộ thơm phức.", "After an hour the whole flat smells good."),
  ("N", "Opa kommt in die Küche und isst ein bisschen von der Suppe.", "Ông vào bếp và ăn thử một chút súp.", "Grandpa comes into the kitchen and eats a little of the soup."),
  ("N", "Er sagt lange nichts. Dann sagt er: Die Suppe schmeckt wunderbar!", "Ông im lặng hồi lâu. Rồi ông nói: Súp ngon tuyệt!", "He says nothing for a long time. Then he says: The soup tastes wonderful!"),
  ("B", "Tim hat heute gekocht.", "Hôm nay Tim nấu đấy.", "Tim cooked today."),
  ("A", "Mit Oma! Und mit sehr viel Salz.", "Cùng với bà ạ! Và với rất nhiều muối.", "With Grandma! And with a lot of salt."),
  ("N", "Alle lachen und essen zusammen. Danach gibt es noch Kekse.", "Mọi người cười vang và cùng ăn. Sau đó còn có bánh quy.", "Everyone laughs and eats together. Afterwards there are biscuits too."),
  ("A", "Mein Magen ist voll!", "Bụng cháu no căng rồi!", "My tummy is full!")],
 [("locate", "Tim cho quá nhiều thứ gì vào súp?", "What does Tim put too much of into the soup?", [("Muối", "Salt"), ("Nước", "Water"), ("Thịt", "Meat")], 0),
  ("locate", "Ai ăn thử súp?", "Who tries the soup?", [("Mẹ của Tim", "Tim's mother"), ("Ông", "Grandpa"), ("Bạn của Tim", "Tim's friend")], 1),
  ("infer", "Vì sao bà cho thêm một củ khoai tây?", "Why does Grandma add another potato?", [("Vì Tim vẫn còn đói", "Because Tim is still hungry"), ("Vì súp quá ít", "Because there is too little soup"), ("Để súp bớt mặn", "To make the soup less salty")], 2)],
 names=["Tim"]))

S.append(story("die_neue_wohnung", "A2-1", "Die neue Wohnung",
 ("Gia đình Schmidt chuyển đến căn hộ mới. Bạn bè giúp một tay — và có một vị khách bất ngờ gõ cửa.", "The Schmidt family moves into a new flat. Friends help — and a surprise visitor knocks at the door."),
 ["klopfen", "Stock", "Leiter"],
 [("N", "Familie Schmidt zieht in eine neue Wohnung.", "Gia đình Schmidt chuyển đến một căn hộ mới.", "The Schmidt family is moving into a new flat."),
  ("N", "Die alte Wohnung war zu klein. Die neue hat vier Zimmer und einen Balkon.", "Căn hộ cũ quá nhỏ. Căn mới có bốn phòng và một ban công.", "The old flat was too small. The new one has four rooms and a balcony."),
  ("N", "Am Samstag kommen viele Freunde und helfen.", "Thứ Bảy nhiều bạn bè đến giúp.", "On Saturday many friends come and help."),
  ("N", "Sie tragen die Möbel die Treppe hoch.", "Họ khiêng đồ đạc lên cầu thang.", "They carry the furniture up the stairs."),
  ("N", "Der Tisch ist schwer, aber die Stühle sind leicht.", "Cái bàn nặng, nhưng mấy cái ghế thì nhẹ.", "The table is heavy, but the chairs are light."),
  ("A", "Wohin kommt das Bett?", "Cái giường để đâu?", "Where does the bed go?"),
  ("B", "Ins Schlafzimmer, neben das Fenster.", "Vào phòng ngủ, cạnh cửa sổ.", "Into the bedroom, next to the window."),
  ("N", "Paul stellt das Sofa in die Mitte vom Zimmer.", "Paul đặt ghế sô-pha ở giữa phòng.", "Paul puts the sofa in the middle of the room."),
  ("N", "Die Kinder legen ihre Bücher auf den Boden.", "Bọn trẻ đặt sách của chúng xuống sàn.", "The children put their books on the floor."),
  ("N", "Für die Bilder brauchen sie eine Leiter.", "Để treo tranh, họ cần một cái thang.", "For the pictures they need a ladder."),
  ("N", "Um zwölf Uhr haben alle Hunger.", "Mười hai giờ mọi người đều đói.", "At twelve everyone is hungry."),
  ("A", "Wir bestellen Pizza!", "Chúng ta gọi pizza đi!", "Let's order pizza!"),
  ("N", "Sie sitzen auf dem Boden und essen. In der Küche gibt es noch keinen Tisch.", "Họ ngồi trên sàn và ăn. Trong bếp vẫn chưa có bàn.", "They sit on the floor and eat. There is no table in the kitchen yet."),
  ("N", "Dann klopft jemand an die Tür.", "Rồi có người gõ cửa.", "Then someone knocks at the door."),
  ("N", "Vor der Tür steht ein alter Mann.", "Trước cửa là một ông lão.", "An old man is standing at the door."),
  ("A", "Guten Tag. Ich bin Herr Braun. Ich wohne unten im ersten Stock.", "Xin chào. Tôi là ông Braun. Tôi sống ở tầng một bên dưới.", "Good afternoon. I'm Mr Braun. I live downstairs on the first floor."),
  ("A", "Hier ist ein Kuchen für Sie. Willkommen im Haus!", "Đây là một cái bánh cho các bạn. Chào mừng đến với tòa nhà!", "Here is a cake for you. Welcome to the building!"),
  ("B", "Vielen Dank! Das ist sehr nett. Kommen Sie doch rein!", "Cảm ơn ông nhiều! Ông thật tốt bụng. Mời ông vào nhà!", "Thank you very much! That's very kind. Do come in!"),
  ("N", "Herr Braun bleibt eine Stunde und erzählt viel über das Haus.", "Ông Braun ở lại một tiếng và kể nhiều chuyện về tòa nhà.", "Mr Braun stays for an hour and tells them a lot about the building."),
  ("N", "Er wohnt hier schon seit dreißig Jahren.", "Ông đã sống ở đây ba mươi năm rồi.", "He has lived here for thirty years."),
  ("N", "Am Abend sind alle müde, aber glücklich.", "Buổi tối mọi người đều mệt, nhưng vui.", "In the evening everyone is tired, but happy."),
  ("B", "Die neue Wohnung ist wunderbar. Und wir haben schon einen Freund im Haus!", "Căn hộ mới tuyệt vời. Và chúng ta đã có một người bạn trong tòa nhà!", "The new flat is wonderful. And we already have a friend in the building!")],
 [("locate", "Căn hộ mới có mấy phòng?", "How many rooms does the new flat have?", [("Hai", "Two"), ("Bốn", "Four"), ("Ba mươi", "Thirty")], 1),
  ("locate", "Ông Braun mang gì đến?", "What does Mr Braun bring?", [("Một cái bánh", "A cake"), ("Một cái thang", "A ladder"), ("Bánh pizza", "Pizza")], 0),
  ("infer", "Vì sao mọi người ngồi ăn trên sàn?", "Why does everyone eat sitting on the floor?", [("Họ thích ngồi dưới sàn", "They like sitting on the floor"), ("Ghế quá nặng", "The chairs are too heavy"), ("Trong bếp chưa có bàn", "There is no table in the kitchen yet")], 2)],
 names=["Schmidt", "Paul", "Braun"]))

S.append(story("der_koenig_und_das_feuer", "A2-1", "Der König und das Feuer",
 ("Một kẻ ác muốn chiếm đất nước của nhà vua. Cô con gái út Ella đi vào rừng tìm sự giúp đỡ.", "An evil man wants to take the king's land. His youngest daughter Ella goes into the forest for help."),
 ["Schloss", "Prinzessin", "Krone"],
 [("N", "Vor langer Zeit lebte ein König in einem großen Schloss.", "Ngày xửa ngày xưa có một nhà vua sống trong một tòa lâu đài lớn.", "A long time ago a king lived in a big castle."),
  ("N", "Er hatte viel Macht und viel Geld, aber er war nicht glücklich.", "Ông có nhiều quyền lực và nhiều tiền, nhưng ông không hạnh phúc.", "He had a lot of power and a lot of money, but he was not happy."),
  ("N", "Er hatte drei Töchter. Die jüngste Prinzessin hieß Ella.", "Ông có ba người con gái. Nàng công chúa út tên là Ella.", "He had three daughters. The youngest princess was called Ella."),
  ("N", "Eines Tages kam ein böser Mann mit einer Armee in das Land.", "Một ngày nọ, một kẻ ác dẫn một đạo quân đến đất nước.", "One day an evil man came into the land with an army."),
  ("A", "Gib mir dein Land, oder ich zerstöre alles!", "Đưa đất nước của ngươi cho ta, nếu không ta sẽ phá hủy tất cả!", "Give me your land, or I will destroy everything!"),
  ("N", "Der König hatte Angst. Seine Soldaten waren schwach.", "Nhà vua sợ hãi. Quân lính của ông yếu ớt.", "The king was afraid. His soldiers were weak."),
  ("N", "Zwei Töchter weinten.", "Hai người con gái khóc.", "Two daughters cried."),
  ("N", "Aber Ella hatte eine Idee.", "Nhưng Ella có một ý.", "But Ella had an idea."),
  ("B", "Vater, ich gehe in den Wald. Dort lebt eine alte Frau. Sie kann uns helfen.", "Cha ơi, con sẽ vào rừng. Ở đó có một bà lão. Bà ấy có thể giúp chúng ta.", "Father, I'm going into the forest. An old woman lives there. She can help us."),
  ("N", "Ella ging allein in den großen Wald.", "Ella một mình đi vào khu rừng lớn.", "Ella went alone into the big forest."),
  ("N", "Die alte Frau saß vor einem kleinen Haus.", "Bà lão ngồi trước một ngôi nhà nhỏ.", "The old woman was sitting in front of a little house."),
  ("B", "Bitte helfen Sie uns! Ein böser Mann will unser Land.", "Xin bà giúp chúng tôi! Một kẻ ác muốn chiếm đất nước của chúng tôi.", "Please help us! An evil man wants our land."),
  ("N", "Die alte Frau gab ihr einen Stein. Der Stein war rot und warm wie Feuer.", "Bà lão đưa cho nàng một hòn đá. Hòn đá đỏ và ấm như lửa.", "The old woman gave her a stone. The stone was red and warm like fire."),
  ("N", "Wirf den Stein vor die Armee, sagte die Frau.", "Hãy ném hòn đá trước đạo quân, bà lão nói.", "Throw the stone in front of the army, the woman said."),
  ("N", "Ella lief schnell zurück.", "Ella chạy nhanh trở về.", "Ella ran back quickly."),
  ("N", "Am nächsten Morgen kam die Armee.", "Sáng hôm sau đạo quân kéo đến.", "The next morning the army came."),
  ("N", "Ella warf den Stein. Da war überall Feuer — aber nur vor den Soldaten.", "Ella ném hòn đá. Lửa bùng lên khắp nơi — nhưng chỉ ở trước mặt quân lính.", "Ella threw the stone. There was fire everywhere — but only in front of the soldiers."),
  ("N", "Die Feinde bekamen Angst und liefen zurück in ihr Land.", "Kẻ thù hoảng sợ và chạy về nước của chúng.", "The enemies got scared and ran back to their land."),
  ("N", "Das Volk war wieder frei.", "Nhân dân lại được tự do.", "The people were free again."),
  ("A", "Ella, du hast uns gerettet!", "Ella, con đã cứu chúng ta!", "Ella, you have saved us!"),
  ("N", "Von diesem Tag an war der König glücklich.", "Từ ngày đó nhà vua hạnh phúc.", "From that day on the king was happy."),
  ("N", "Und Ella? Viele Jahre später trug sie die Krone.", "Còn Ella? Nhiều năm sau nàng đội vương miện.", "And Ella? Many years later she wore the crown.")],
 [("locate", "Bà lão đưa cho Ella cái gì?", "What does the old woman give Ella?", [("Một hòn đá đỏ", "A red stone"), ("Một vương miện", "A crown"), ("Một đạo quân", "An army")], 0),
  ("locate", "Ella đi đâu để tìm sự giúp đỡ?", "Where does Ella go for help?", [("Đến một lâu đài khác", "To another castle"), ("Vào rừng", "Into the forest"), ("Ra biển", "To the sea")], 1),
  ("infer", "Vì sao kẻ thù bỏ chạy?", "Why do the enemies run away?", [("Nhà vua đưa tiền cho chúng", "The king gave them money"), ("Quân lính của nhà vua rất mạnh", "The king's soldiers were very strong"), ("Lửa bùng lên trước mặt chúng", "Fire appeared in front of them")], 2)],
 names=["Ella"], token_map={"jüngste": "jung"}))

lib.write_batch("03", S)
